const COLORS = {
    pink: '#FF4E8A', purple: '#7B5CF5', blue: '#3DBEF5',
    teal: '#1DD8B4', orange: '#FF8C42', green: '#4CAF7D', yellow: '#FFD166'
};

const CELL_COLORS = ['#FF4E8A', '#FFD166', '#4CAF7D', '#3DBEF5', '#7B5CF5', '#FF8C42'];

function FloatingGrid() {
    const cells = [
        { n: '1', c: 0 }, { n: '4', c: 2 }, { n: '2', c: 3 }, { n: '3', c: 1 }, { n: '6', c: 4 }, { n: '', c: -1 },
        { n: '', c: -1 }, { n: '2', c: 5 }, { n: '6', c: 2 }, { n: '', c: -1 }, { n: '', c: -1 }, { n: '', c: -1 },
        { n: '4', c: 3 }, { n: '6', c: 5 }, { n: '2', c: 0 }, { n: '', c: -1 }, { n: '', c: -1 }, { n: '', c: -1 },
        { n: '', c: -1 }, { n: '5', c: 1 }, { n: '3', c: 2 }, { n: '', c: -1 }, { n: '6', c: 4 }, { n: '', c: -1 },
        { n: '3', c: 2 }, { n: '', c: -1 }, { n: '', c: -1 }, { n: '6', c: 5 }, { n: '1', c: 0 }, { n: '', c: -1 },
        { n: '', c: -1 }, { n: '4', c: 3 }, { n: '1', c: 0 }, { n: '', c: -1 }, { n: '2', c: 1 }, { n: '5', c: 4 },
    ];
    return (
        <div className="floating-grid">
            {cells.map((cell, i) => (
                <div key={i} className="grid-cell" style={{
                    background: cell.c >= 0 ? CELL_COLORS[cell.c] : 'rgba(255,255,255,0.06)',
                    color: cell.c >= 0 ? 'white' : 'transparent',
                }}>{cell.n}</div>
            ))}
        </div>
    );
}

function MiniSudoku({ size = 4, colorScheme = 'pink' }) {
    const colors4 = ['#FF4E8A', '#FFD166', '#4CAF7D', '#3DBEF5'];
    const grid4 = [[1, 0, 2, 3], [3, 0, 4, 1], [4, 1, 3, 2], [2, 3, 0, 4]];
    const cols = size === 4 ? 'repeat(4, 1fr)' : 'repeat(6, 1fr)';
    return (
        <div className="mini-sudoku" style={{ gridTemplateColumns: cols }}>
            {grid4.map((row, r) => row.map((v, c) => (
                <div key={`${r}-${c}`} className="ms-cell" style={{
                    background: v === 0 ? 'rgba(255,255,255,0.06)' : colors4[v - 1],
                    color: 'white'
                }}>{v || ''}</div>
            )))}
        </div>
    );
}

